const x=$('OPS | Input').first()?.json||{};
const turn=x.turn||{};
const state=x.state||{};
const b=x.brain||{};

let action=String(b.action||'respond');
const actor=String(turn.actor_type||'cliente');

// Overrides permitidos: identidade interna e takeover real.
if(actor==='vendedor'||actor==='coordenacao') action='internal_actor';
else if(state.human_takeover_blocked===true||state.human_takeover===true) action='silent_human';

const featurePhone=String(turn.phone||state.telefone||'').replace(/\D/g,'');
const useConversationV2=x.feature_flags?.conversation_v2===true || state.feature_flags?.conversation_v2===true;
const alreadyAssigned=Boolean(state?.vendedor_atual?.id||state?.vendedor_atual?.nome||state?.oportunidade?.vendedor_id);
const technicalOpen=b.technical_open===true || (state?.lino_v9_state?.technical_open===true && b.technical_open!==false);
const nonCommercialIntent=['general','careers','institutional','out_of_portfolio'].includes(String(b.intent||''));
if(action==='respond' || nonCommercialIntent){
  // Resposta direta nunca entra no pipeline SDR/distribuicao.
  action='respond';
} else if(useConversationV2 && !alreadyAssigned && !technicalOpen){
  if(['ask','route_rules'].includes(action)) action='route_rules';
  if(action==='quote_complement') action='route_rules';
}

const norm=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
function productSlugFrom(text){
  const t=norm(text).replace(/[_-]+/g,' ');
  if(!t) return null;
  if(/grade\s+de\s+piso|grade\s+eletrofundida/.test(t)) return 'grade_piso';
  if(/degrau/.test(t)&&/grade|piso/.test(t)) return 'degrau_grade_piso';
  if(/gradil/.test(t)) return 'gradil_metalico';
  if(/chapa\s+perfurada|perfurad[ao]/.test(t)) return 'chapa_perfurada';
  if(/chapa\s+expandida/.test(t)) return 'chapa_expandida';
  if(/chapa\s+recalcada|recalcad[ao]/.test(t)) return 'chapa_recalcada';
  if(/telha\s+trapezoidal|trapezoidal/.test(t)) return 'telha_trapezoidal';
  if(/telha\s+(?:ondulada|ondulado)|cobertura\s+ondulada/.test(t)) return 'telha_ondulada';
  if(/tela\s+expandida/.test(t)) return 'tela_expandida';
  if(/tela\s+moeda/.test(t)) return 'tela_moeda';
  if(/forro/.test(t)) return 'forro_metalico';
  if(/brise/.test(t)) return 'brise_metalico';
  if(/port[aã]o/.test(t)&&/gradil/.test(t)) return 'portao_gradil';
  if(/piso\s+industrial/.test(t)) return 'piso_industrial';
  return null;
}

const facts=Array.isArray(b.facts_to_store)?b.facts_to_store:[];
const normalizeOrigin=v=>{
  const s=String(v||'').toLowerCase().trim();
  if(['cliente_informou','cliente_escolheu','inferido_contexto','sugestao_lino_aceita','validacao_tecnica_pendente'].includes(s)) return s;
  if(['mensagem_cliente','cliente','whatsapp','mensagem_atual'].includes(s)) return 'cliente_informou';
  if(['historico_recente','historico_cliente','memoria','contexto'].includes(s)) return 'inferido_contexto';
  return 'inferido_contexto';
};
let updates=(Array.isArray(b.commercial_updates)?b.commercial_updates:[])
  .map(u=>u&&typeof u==='object'?{
    campo:u.campo??u.field??null,
    valor:u.valor??u.value??null,
    origem:normalizeOrigin(u.origem??u.source??'cliente_informou'),
    confianca:u.confianca??u.confidence??'alta'
  }:null)
  .filter(u=>u?.campo&&u.valor!==undefined&&u.valor!==null);

const looksLikeInternalBlob=v=>{
  const s=String(v??'').trim();
  return !s || s.length>220 || /\[ANALISE_IMAGEM\]|\[CONTEXTO VISUAL RECENTE\]|encrypted_content|gAAAAA|\\"type\\":\\"reasoning\\"|output_text/i.test(s);
};
updates=updates.filter(u=>{
  if(u.campo==='quantidade') return !looksLikeInternalBlob(u.valor);
  if(['empresa','cnpj','email','nome','segmento','produto'].includes(String(u.campo))) return String(u.valor??'').length<=500 && !looksLikeInternalBlob(u.valor);
  return true;
});

const stateSubject=
  productSlugFrom(state?.produto_slug) ||
  productSlugFrom(state?.lino_v9_state?.current_subject) ||
  productSlugFrom(state?.comercial?.dados_atuais?.produto) ||
  null;
const updateProduct=updates.find(u=>u.campo==='produto');
const productSlug=
  productSlugFrom(turn.content||turn.text||'') ||
  stateSubject ||
  productSlugFrom(updateProduct?.valor) ||
  productSlugFrom(b.current_subject) ||
  null;
const specialProject=['telha_ondulada','telha_trapezoidal'].includes(String(productSlug||''));
if(specialProject && !alreadyAssigned){
  if(['respond','ask','quote_complement','route_rules'].includes(action)) action='route_rules';
}

const oppId=
  state?.oportunidade?.id ||
  state?.comercial?.oportunidade_id ||
  state?.oportunidade_id ||
  null;
const objFact=facts.find(f=>f&&typeof f==='object'&&!Array.isArray(f))||{};
const factText=facts.filter(f=>typeof f==='string').join(' | ');
const findUpdate=campo=>updates.find(u=>u?.campo===campo)?.valor??null;

const qtyMatch=factText.match(/quantidade\s*:\s*([^|]+)/i);
const segMatch=factText.match(/segmento\s*:\s*([^|]+)/i);
const sourceText=String(turn.content||turn.text||'');
const awaitedStage=String(state?.conversa?.campo_aguardado||state?.conversa?.ultima_pergunta||'');
const awaitingFinalConfirmation =
  state?.conversa?.confirmacao_pendente===true ||
  awaitedStage==='confirmacao_final';
const awaitingLgpd = awaitedStage==='lgpd_final';
const normalizedFinalReply=norm(sourceText).replace(/[.!?]+$/g,'').trim();
const yesReply=/^(sim|s|ok|certo|correto|confirmo|confirmado|pode|pode sim|pode encaminhar|pode enviar)$/.test(normalizedFinalReply);
const noReply=/^(nao|não|n|nao esta|não esta|incorreto|errado)$/.test(normalizedFinalReply);
const lgpdYes=/^(sim|s|ok|autorizo|autorizado|pode|pode sim|pode compartilhar|pode enviar)$/.test(normalizedFinalReply);
const lgpdNo=/^(nao|não|n|nao autorizo|não autorizo|nao quero|não quero|recuso)$/.test(normalizedFinalReply);

if(awaitingFinalConfirmation && yesReply){
  b.confirmation_client=true;
  b.confirmacao_cliente=true;
  b.lgpd_share_consent=null;
  b.lgpd_status=null;
  b.answer=null;
  b.question='Você autoriza o compartilhamento desses dados com o vendedor responsável pelo atendimento?';
  action='lgpd';
}
if(awaitingFinalConfirmation && noReply){
  b.confirmation_client=false;
  b.confirmacao_cliente=false;
  b.lgpd_share_consent=null;
  b.lgpd_status=null;
  b.answer='Claro.';
  b.question='O que devo corrigir no resumo?';
  action='ask';
}
if(awaitingLgpd && lgpdYes){
  b.lgpd_share_consent='accepted';
  b.lgpd_status='accepted';
  b.question=null;
  action='lgpd';
}
if(awaitingLgpd && lgpdNo){
  b.lgpd_share_consent='refused';
  b.lgpd_status='refused';
  b.question=null;
  action='lgpd';
}
const directQty=sourceText.match(/\b(\d+(?:[.,]\d+)?)\s*(chapas?|pe[cç]as?|unidades?|un\b|m\s*[2²]|kg\b|metros?\b)/i);
const sanitizeQuantity=v=>{
  const s=String(v??'').trim();
  if(!s || looksLikeInternalBlob(s)) return null;
  if(!/\d/.test(s)) return null;
  return s.slice(0,120);
};
const quantity=sanitizeQuantity(
  findUpdate('quantidade')||
  objFact.quantidade||
  (qtyMatch?qtyMatch[1].trim():null)||
  (directQty?directQty[1]+' '+directQty[2]:null)||
  state?.comercial?.dados_atuais?.quantidade||
  state?.oportunidade?.quantidade||
  null
);
let segment=findUpdate('segmento')||objFact.segmento||(segMatch?segMatch[1].trim().toLowerCase():null)||state?.comercial?.dados_atuais?.segmento||null;
if(segment==='industria') segment='industrial';
if(segment==='construção') segment='construcao';

const contextText=norm([
  sourceText,
  b.technical_summary||'',
  state?.lino_v9_state?.technical_summary||'',
  state?.pre_especificacao||''
].join(' '));

const tipoClienteRaw=String(
  b.tipo_cliente || b.customer_type ||
  state?.tipo_cliente || state?.comercial?.tipo_cliente ||
  state?.qualification_state?.tipo_cliente || ''
).toLowerCase().trim();
const tipoCliente = ['pf','pessoa_fisica','pessoa física','pessoa fisica'].includes(tipoClienteRaw) ? 'pf'
  : (['pj','pessoa_juridica','pessoa jurídica','pessoa juridica'].includes(tipoClienteRaw) ? 'pj' : null);
const neverExpress=new Set(['grade_piso','degrau_grade_piso','tela_antiofuscante','chapa_moeda','tela_moeda','belaco','bobina_moeda','gradinox']);
const qtyUnitMatch=String(quantity||'').match(/(\d+(?:[.,]\d+)?)\s*(chapas?|pe[cç]as?|unidades?|un\b)/i);
const qtyUnits=qtyUnitMatch?Number(qtyUnitMatch[1].replace(',','.')):null;
const dims3x1=/\b3\s*[xX]\s*1\b|3000\s*[xX]\s*1000/i.test(contextText);
const sheetLike=/^(chapa_|tela_)/.test(String(productSlug||''))&&!neverExpress.has(String(productSlug||''));
const ownUseCue=/minha loja|loja propria|uso proprio|uso interno|mobilia|mobiliario|movel|moveis|para meu negocio|consumo proprio/.test(contextText);
const blockedExpressSegment=['industrial','industria','revenda'].includes(String(segment||'').toLowerCase());
const smallByUnits=qtyUnits!==null&&qtyUnits>0&&qtyUnits<=(dims3x1?10:15);
const expressSmallOrder = tipoCliente==='pf' || (sheetLike&&smallByUnits&&!blockedExpressSegment&&(ownUseCue||['construcao','serralheria'].includes(String(segment||''))));

const legacyUpdates=updates.map(u=>u?.campo==='segmento'&&u?.valor==='industria'?{...u,valor:'industrial'}:u);
if(segment&&!legacyUpdates.some(u=>u?.campo==='segmento')) legacyUpdates.push({campo:'segmento',valor:segment,origem:'inferido_contexto',confianca:'alta'});
if(quantity&&!legacyUpdates.some(u=>u?.campo==='quantidade')) legacyUpdates.push({campo:'quantidade',valor:String(quantity),origem:'cliente_informou',confianca:'alta'});

let answer=String(b.answer||'').trim();
let question=String(b.question||'').trim();

// PF e sempre EXPRESS: empresa, CNPJ e segmento nao devem bloquear nem virar pergunta.
if(tipoCliente==='pf'){
  if(/empresa|cnpj|segmento|ind[uú]stria|constru[cç][aã]o|revenda|serralheria/i.test(question)) question='';
  action='route_rules';
}
if(question && answer.includes('?')){
  answer=answer.replace(/(^|[\n\s])[^.!?\n]*\?/g,' ').replace(/\s{2,}/g,' ').trim();
}
const asksKnownProduct=/qual produto|produto.*procura|qual.*produto|o que deseja cotar|qual solu[cç][aã]o/i.test(question);
if(expressSmallOrder && /ind[uú]stria|constru[cç][aã]o|revenda|serralheria|segmento|perfil da empresa/i.test(question)){
  question='';
  action='route_rules';
}
if(productSlug&&asksKnownProduct){
  if(!quantity) question='Qual é a quantidade aproximada que você precisa?';
  else if(!segment) question='Essa compra é para indústria, construção, revenda ou serralheria?';
  else question='';
}
if(specialProject){
  const technicalAsk=/perfil|onda|passo|altura|dobra|conforma|raio|desenho tecnico|capacidade|carga|vao|fixacao|apoio|modelo padrao/i.test(question);
  if(technicalAsk) question='';
  if(!quantity && !question) question='Qual é a quantidade aproximada que você precisa?';
  else if(quantity && !segment && !question) question='Essa compra é para indústria, construção, revenda ou serralheria?';
}
const responseText=[answer,question&&question!==answer&&!answer.toLowerCase().includes(question.toLowerCase())?question:null].filter(Boolean).join('\n\n');

const qLower=question.toLowerCase();
let awaitedField=b?.seller_readiness?.next_field||null;
if(!awaitedField&&question){
  if(/nome da empresa|qual.*empresa|empresa solicitante/.test(qLower)) awaitedField='empresa';
  else if(/cnpj/.test(qLower)) awaitedField='cnpj';
  else if(/e-?mail/.test(qLower)) awaitedField='email';
  else if(/quantidade|quanto.*precisa|quantos|quantas/.test(qLower)) awaitedField='quantidade';
  else if(/ind[uú]stria|constru[cç][aã]o|revenda|serralheria|segmento|perfil da empresa/.test(qLower)) awaitedField='segmento';
  else if(/seu nome|nome completo|como.*chama/.test(qLower)) awaitedField='nome';
}
if(!['empresa','cnpj','email','quantidade','nome','segmento'].includes(String(awaitedField||''))) awaitedField=null;
if(tipoCliente==='pf' && ['empresa','cnpj','segmento'].includes(String(awaitedField||''))) awaitedField=null;
if(expressSmallOrder && awaitedField==='segmento') awaitedField=null;
if(technicalOpen && !specialProject) awaitedField=null;

const prevTechCount=Number(state?.lino_v9_state?.technical_questions_consecutive||0);
const currentQuestion=String(b.question||'');
const isTechnicalQuestion=/carga|impacto|proje[cç][aã]o|dist[aâ]ncia|apoio|fixa[cç][aã]o|flecha|risco|zona perigosa|v[aã]o|roda|eixo|área de contato|area de contato/i.test(currentQuestion);
const technicalQuestionsConsecutive=isTechnicalQuestion?prevTechCount+1:0;

const structuredState={
  version:3,
  current_subject:productSlug,
  intent:b.intent||'general',
  action,
  relation_to_previous:b.relation_to_previous||'unknown',
  technical_summary:b.technical_summary||state?.lino_v9_state?.technical_summary||null,
  technical_questions_consecutive:technicalQuestionsConsecutive,
  technical_open:specialProject?false:technicalOpen,
  special_project:specialProject,
  special_project_reason:specialProject?'telha_conformada_validacao_por_projeto':null,
  psa_aplicacao_arquitetonica:b.psa_aplicacao_arquitetonica===true || state?.contextual_routing_hint?.psa_aplicacao_arquitetonica===true,
  express_small_order:expressSmallOrder,
  express_reason:tipoCliente==='pf'?'cliente_pf_express_soberano':(expressSmallOrder?'pequeno_pedido_chapa_tela_nao_industria_nao_revenda':null),
  tipo_cliente:tipoCliente,
  skip_enrichment_due_impatience:b.skip_enrichment_due_impatience===true,
  knowledge_sources:Array.isArray(b.knowledge_sources)?b.knowledge_sources:[],
  technical_compatibility:b.technical_compatibility||{status:'not_applicable',product:null,reason:null,engineering_validation_required:false},
  seller_readiness:expressSmallOrder
    ? {status:'ready',missing_fields:[],next_field:null,reason:'express_pequeno_pedido'}
    : (specialProject
      ? (quantity&&segment
        ? {status:'ready',missing_fields:[],next_field:null,reason:'projeto_especial_minimo_rota_completo'}
        : {status:'missing',missing_fields:[!quantity?'quantidade':null,!segment?'segmento':null].filter(Boolean),next_field:!quantity?'quantidade':(!segment?'segmento':null),reason:'projeto_especial_minimo_rota'})
      : (b.seller_readiness||{status:'unknown',missing_fields:[],next_field:null,reason:null})),
  facts_to_store:facts,
  commercial_updates:legacyUpdates,
  source_message:String(turn.content||turn.text||''),
  updated_at:new Date().toISOString()
};

const legacyPayload={
  acao:(action==='handoff'||(action==='lgpd'&&b.lgpd_status==='refused'))?'handoff_humano':(action==='route_rules'?'encaminhar':'continuar'),
  tipo_cliente:tipoCliente,
  structured_state:structuredState,
  confirmacao_cliente:b.confirmation_client===true || b.confirmacao_cliente===true,
  lgpd_share_consent:b.lgpd_share_consent||null,
  produto:{slug:productSlug,confianca:b.confidence==='high'?'alta':'media'},
  atualizacoes_comerciais:legacyUpdates,
  dados_tecnicos:[],
  especificacao_livre:b.technical_summary||null,
  solicitacoes_cliente:[],
  campos_solicitados:awaitedField?[awaitedField]:[],
  estado_conversa:{ultima_pergunta:question||null,campo_aguardado:awaitedField,sugestao_pendente:null},
  intencao_cliente:b.intent||'outro',
  duvida_cliente:String(turn.content||turn.text||''),
  orientacao_resposta:b.answer||b.question||null
};

return [{json:{...x,action,original_action:String(b.action||'respond'),use_conversation_v2:useConversationV2,product_slug:productSlug,quantity:quantity?String(quantity):null,segment,oportunidade_id:oppId,response_text:responseText,legacy_payload:legacyPayload,decision_source:'brain'}}];

const r = $input.first()?.json?.result ?? {};
const p = $('OPS | Planejar').first().json || {};
const text = String(p.turn?.content || p.turn?.text || '');

if (r.ambiguous) {
  return [{
    json: {
      mode: 'reply_only',
      reply: 'Encontrei mais de um atendimento aberto. Responda novamente incluindo o código LINO do atendimento.'
    }
  }];
}

if (!r.encontrado) {
  return [{
    json: {
      mode: 'reply_only',
      reply: 'Não encontrei atendimento de suporte aberto para você agora.'
    }
  }];
}

const t = text.toLowerCase();
let tipo = 'JUSTIFICATIVA';
let prazo = null;
let justificativa = text;
let m = null;

if (/resolvid|conclu[ií]|finaliz|enviado.*(or[cç]amento|cota[cç][aã]o|proposta)/i.test(t)) {
  tipo = 'RESOLVIDO';
} else if (/pode transferir|pode passar|n[aã]o consigo atender|indispon[ií]vel|f[eé]rias|afastad/i.test(t)) {
  tipo = 'JUSTIFICATIVA';
  justificativa = 'SOLICITA_TRANSFERENCIA: ' + text;
} else if ((m = t.match(/(?:em|daqui a|prazo)\s*(\d+)\s*(min|minuto|minutos|h|hora|horas|dia|dias)/i))) {
  const n = Number(m[1]);
  const u = m[2];
  const ms = u.startsWith('min')
    ? n * 60000
    : (u === 'h' || u.startsWith('hora'))
      ? n * 3600000
      : n * 86400000;
  prazo = new Date(Date.now() + ms).toISOString();
  tipo = 'PRAZO';
} else if ((m = t.match(/(?:at[eé]|por volta de|retorno.*?)(\d{1,2})(?::(\d{2}))?\s*h?/i))) {
  const now = new Date();
  const h = Number(m[1]);
  const min = Number(m[2] || 0);
  const d = new Date(now);
  if ((h * 60 + min) <= (now.getHours() * 60 + now.getMinutes())) d.setDate(d.getDate() + 1);
  d.setHours(h, min, 0, 0);
  prazo = d.toISOString();
  tipo = 'PRAZO';
} else if (/atendi|falei|conversei|contatei|chamei/i.test(t)) {
  tipo = 'ATENDI';
}

let reply = 'Sua atualização foi registrada no acompanhamento.';
if (tipo === 'ATENDI') reply = 'Contato com o cliente registrado. Obrigado.';
else if (tipo === 'PRAZO') reply = 'Prazo registrado.';
else if (tipo === 'RESOLVIDO') reply = 'Atendimento marcado como resolvido. Obrigado.';

return [{
  json: {
    mode: 'record',
    support_case_id: r.case?.id,
    tipo,
    prazo,
    justificativa: tipo === 'JUSTIFICATIVA' ? justificativa : null,
    reply
  }
}];

const body = $input.first()?.json?.result ?? $input.first()?.json ?? {};
const d = body.decision || {};
const c = d.contexto?.contato || {};
const v = d.contexto?.vendedor || {};
const coord = d.contexto?.coordenacao || {};
const ac = String(d.acao || '');
const p = $('OPS | Planejar').first().json || {};

let client = p.response_text || 'Localizei seu atendimento e vou acompanhar por aqui.';

if (ac.includes('aguardar')) {
  client = 'Seu atendimento segue em acompanhamento e o prazo vigente ainda não terminou.';
} else if (ac.includes('cobrar_vendedor')) {
  client = 'Vou acionar o vendedor responsável agora e acompanhar o retorno.';
} else if (ac.includes('escalar_coordenacao')) {
  client = 'Vou acionar a coordenação comercial para acompanhar este caso.';
}

let internal = null;

if (d.notificar_coordenacao) {
  internal = {
    phone: String(coord.telefone || '').replace(/\D/g, ''),
    text: [
      'ESCALAÇÃO LINO',
      'Cliente: ' + String(c.nome || c.telefone || ''),
      'Mensagem: ' + String(p.turn?.content || '')
    ].join(String.fromCharCode(10)),
    kind: 'coord'
  };
} else if (d.notificar_vendedor) {
  internal = {
    phone: String(v.telefone || '').replace(/\D/g, ''),
    text: [
      'ACOMPANHAMENTO LINO',
      'Cliente: ' + String(c.nome || c.telefone || ''),
      'Mensagem: ' + String(p.turn?.content || '')
    ].join(String.fromCharCode(10)),
    kind: 'seller'
  };
}

return [{
  json: {
    ...p,
    client_text: client,
    support_case_id: body.support_case_id || null,
    internal
  }
}];

const raw = $input.first()?.json || {};
const b = raw.result ?? raw.body ?? raw;
const p = $('OPS | Planejar').first().json || {};

let newQuoteId = null;
try { newQuoteId = $('OPS | Nova Cotacao').first().json?.result?.oportunidade_id || null; } catch (e) {}

const oportunidadeId =
  b.oportunidade_id ||
  b.oportunidade?.id ||
  newQuoteId ||
  p.oportunidade_id ||
  null;

const s = b.vendedor || {};
const ready = b.finalizacao?.finalizado === true && !!s.telefone;
const summary = b.resumo_confirmacao || null;
const effectiveAction = String(b.acao_efetiva || 'continuar');
const backendContext = b.contexto_comercial || {};

function fmtSummary(r) {
  if (!r || typeof r !== 'object') return null;
  const lines = ['Antes de encaminhar, confira se registrei corretamente:'];
  if (r.produto) lines.push('Produto: ' + r.produto);
  if (r.segmento) lines.push('Aplicação/segmento: ' + r.segmento);
  if (r.quantidade) lines.push('Quantidade: ' + r.quantidade);
  if (r.empresa) lines.push('Empresa: ' + r.empresa);
  if (r.cnpj) lines.push('CNPJ: ' + r.cnpj);
  if (r.email) lines.push('E-mail: ' + r.email);
  const tech = String(r.pre_especificacao || r.especificacao || '').trim();
  if (tech) lines.push('Pré-especificação: ' + tech);
  lines.push('Está correto? Se algo estiver diferente, me diga o que devo corrigir.');
  return lines.join('\n');
}

let responseText = p.response_text || null;

// Operations só executa contratos determinísticos do backend.
// Ele NÃO cria a próxima pergunta comercial. A pergunta pertence ao Brain.
if (effectiveAction === 'confirmar_dados') {
