  if(/chapa\s+expandida/.test(t)) return 'chapa_expandida';
  if(/chapa\s+recalcada|recalcad[ao]/.test(t)) return 'chapa_recalcada';
  if(/telha\s+trapezoidal|trapezoidal/.test(t)) return 'telha_trapezoidal';
  if(/telha\s+(?:ondulada|ondulado)|cobertura\s+ondulada/.test(t)) return 'telha_ondulada';
  if(/tela\s+expandida/.test(t)) return 'tela_expandida';
  if(/tela\s+moeda/.test(t)) return 'tela_moeda';
  if(/forro/.test(t)) return 'forro_metalico';
  if(/brise/.test(t)) return 'brise_metalico';
  if(/port[aã]o/.test(t)&&/gradil/.test(t)) return 'portao_gradil';
