const t = text.toLowerCase();
let tipo = 'JUSTIFICATIVA';
let prazo = null;
let justificativa = text;
let m = null;

if (/resolvid|conclu[ií]|finaliz|enviado.*(or[cç]amento|cota[cç][aã]o|proposta)/i.test(t)) {
  tipo = 'RESOLVIDO';
} else if (/pode transferir|pode passar|n[aã]o consigo atender|indispon[ií]vel|f[eé]rias|afastad/i.test(t)) {
  tipo = 'JUSTIFICATIVA';
  justificativa = 'SOLICITA_TRANSFERENCIA: ' + text;
} else if ((m = t.match(/(?:em|daqui a|prazo)\s*(\d+)\s*(min|minuto|minutos|h|hora|horas|dia|dias)/i))) {
  const n = Number(m[1]);
  const u = m[2];
  const ms = u.startsWith('min')
    ? n * 60000
    : (u === 'h' || u.startsWith('hora'))
      ? n * 3600000
      : n * 86400000;
  prazo = new Date(Date.now() + ms).toISOString();
  tipo = 'PRAZO';
} else if ((m = t.match(/(?:at[eé]|por volta de|retorno.*?)(\d{1,2})(?::(\d{2}))?\s*h?/i))) {
  const now = new Date();
  const h = Number(m[1]);
  const min = Number(m[2] || 0);
  const d = new Date(now);
  if ((h * 60 + min) <= (now.getHours() * 60 + now.getMinutes())) d.setDate(d.getDate() + 1);
  d.setHours(h, min, 0, 0);
  prazo = d.toISOString();
  tipo = 'PRAZO';
} else if (/atendi|falei|conversei|contatei|chamei/i.test(t)) {
  tipo = 'ATENDI';
}

let reply = 'Sua atualização foi registrada no acompanhamento.';
if (tipo === 'ATENDI') reply = 'Contato com o cliente registrado. Obrigado.';
else if (tipo === 'PRAZO') reply = 'Prazo registrado.';
else if (tipo === 'RESOLVIDO') reply = 'Atendimento marcado como resolvido. Obrigado.';

return [{
  json: {
    mode: 'record',
    support_case_id: r.case?.id,
    tipo,
    prazo,
    justificativa: tipo === 'JUSTIFICATIVA' ? justificativa : null,
    reply
  }
}];

const body = $input.first()?.json?.result ?? $input.first()?.json ?? {};
const d = body.decision || {};
const c = d.contexto?.contato || {};
const v = d.contexto?.vendedor || {};
const coord = d.contexto?.coordenacao || {};
const ac = String(d.acao || '');
const p = $('OPS | Planejar').first().json || {};

let client = p.response_text || 'Localizei seu atendimento e vou acompanhar por aqui.';

if (ac.includes('aguardar')) {
  client = 'Seu atendimento segue em acompanhamento e o prazo vigente ainda não terminou.';
} else if (ac.includes('cobrar_vendedor')) {
  client = 'Vou acionar o vendedor responsável agora e acompanhar o retorno.';
} else if (ac.includes('escalar_coordenacao')) {
  client = 'Vou acionar a coordenação comercial para acompanhar este caso.';
}

let internal = null;

if (d.notificar_coordenacao) {
  internal = {
    phone: String(coord.telefone || '').replace(/\D/g, ''),
    text: [
      'ESCALAÇÃO LINO',
      'Cliente: ' + String(c.nome || c.telefone || ''),
      'Mensagem: ' + String(p.turn?.content || '')
    ].join(String.fromCharCode(10)),
    kind: 'coord'
  };
} else if (d.notificar_vendedor) {
  internal = {
    phone: String(v.telefone || '').replace(/\D/g, ''),
    text: [
      'ACOMPANHAMENTO LINO',
      'Cliente: ' + String(c.nome || c.telefone || ''),
      'Mensagem: ' + String(p.turn?.content || '')
    ].join(String.fromCharCode(10)),
    kind: 'seller'
  };
}

return [{
  json: {
    ...p,
    client_text: client,
    support_case_id: body.support_case_id || null,
    internal
  }
}];

const raw = $input.first()?.json || {};
const b = raw.result ?? raw.body ?? raw;
const p = $('OPS | Planejar').first().json || {};

let newQuoteId = null;
try { newQuoteId = $('OPS | Nova Cotacao').first().json?.result?.oportunidade_id || null; } catch (e) {}

const oportunidadeId =
  b.oportunidade_id ||
  b.oportunidade?.id ||
  newQuoteId ||
  p.oportunidade_id ||
  null;

const s = b.vendedor || {};
const ready = b.finalizacao?.finalizado === true && !!s.telefone;
const summary = b.resumo_confirmacao || null;
const effectiveAction = String(b.acao_efetiva || 'continuar');
const backendContext = b.contexto_comercial || {};

function fmtSummary(r) {
  if (!r || typeof r !== 'object') return null;
  const lines = ['Antes de encaminhar, confira se registrei corretamente:'];
  if (r.produto) lines.push('Produto: ' + r.produto);
  if (r.segmento) lines.push('Aplicação/segmento: ' + r.segmento);
  if (r.quantidade) lines.push('Quantidade: ' + r.quantidade);
  if (r.empresa) lines.push('Empresa: ' + r.empresa);
  if (r.cnpj) lines.push('CNPJ: ' + r.cnpj);
  if (r.email) lines.push('E-mail: ' + r.email);
  const tech = String(r.pre_especificacao || r.especificacao || '').trim();
  if (tech) lines.push('Pré-especificação: ' + tech);
  lines.push('Está correto? Se algo estiver diferente, me diga o que devo corrigir.');
  return lines.join('\n');
}

let responseText = p.response_text || null;

// Operations só executa contratos determinísticos do backend.
// Ele NÃO cria a próxima pergunta comercial. A pergunta pertence ao Brain.
if (effectiveAction === 'confirmar_dados') {
  responseText = fmtSummary(summary) || responseText;
} else if (effectiveAction === 'aguardar_confirmacao') {
  responseText = fmtSummary(summary) || responseText || 'Só preciso confirmar se o resumo está correto antes de seguir.';
}

const shareAccepted = String(
  p.brain?.lgpd_share_consent ||
  p.state?.lgpd?.status ||
  p.brain?.lgpd_status ||
  ''
).toLowerCase() === 'accepted';

const sellerText = [
  'NOVA SOLICITAÇÃO LINO',
  p.product_slug ? 'Produto: ' + p.product_slug : null,
  'Cliente: ' + String(p.turn?.phone || ''),
  p.brain?.technical_summary ? 'Detalhes: ' + p.brain.technical_summary : null,
  shareAccepted && backendContext?.dados_atuais?.empresa ? 'Empresa: ' + backendContext.dados_atuais.empresa : null,
  shareAccepted && backendContext?.dados_atuais?.cnpj ? 'CNPJ: ' + backendContext.dados_atuais.cnpj : null,
  shareAccepted && backendContext?.dados_atuais?.email ? 'E-mail: ' + backendContext.dados_atuais.email : null,
  'Mensagem: ' + String(p.turn?.content || p.turn?.text || '')
].filter(Boolean).join(String.fromCharCode(10));

return [{
  json: {
    ...p,
    oportunidade_id: oportunidadeId,
    ready,
    seller_phone: String(s.telefone || '').replace(/\D/g, ''),
    seller_name: s.nome || '',
    seller_id: s.id || null,
    seller_team: s.equipe || null,
    route_type: b.rota?.tipo_rota || null,
    seller_text: sellerText,
    response_text: responseText,
    route_result: b,
    backend_action: effectiveAction,
    backend_context: backendContext,
    decision_owner: 'brain',
    ops_question_generated: false
  }
}];

const x=$input.first()?.json||{};
const p=$('OPS | Planejar').first().json||{};
const b=x.route_result||{};
const effective=String(x.backend_action||b.acao_efetiva||'continuar');
const text=String(x.response_text||p.response_text||'').trim();
const opId=x.oportunidade_id||p.oportunidade_id||null;

// Operations nao cria pergunta. Brain e a unica autoridade conversacional.
if(effective==='confirmar_dados'){
  return [{json:{ok:true,silent:!text,client_text:text||null,oportunidade_id:opId,action:'confirm_data',backend_action:effective,decision_owner:'brain'}}];
}
if(effective==='aguardar_confirmacao'){
  return [{json:{ok:true,silent:!text,client_text:text||null,oportunidade_id:opId,action:'await_confirmation',backend_action:effective,decision_owner:'brain'}}];
}
if(effective==='continuar'){
  return [{json:{ok:true,silent:!text,client_text:text||null,oportunidade_id:opId,action:'continue',backend_action:effective,decision_owner:'brain',ops_question_generated:false}}];
}
// Se o backend ainda nao confirmou handoff, nunca inventar texto de conclusao.
return [{json:{ok:true,silent:!text,client_text:text||null,oportunidade_id:opId,action:'handoff_pending',backend_action:effective,decision_owner:'brain',ops_question_generated:false}}];

const raw = $input.first()?.json || {};
const r = raw.result ?? raw.body ?? raw;
const p = $('OPS | Preparar Handoff').first().json || {};

const ready = r?.ready === true;
const alreadySent = r?.already_sent === true || r?.motivo === 'ja_submetido_meta';
const inProgress = r?.motivo === 'notificacao_em_andamento';

let clientText = null;
if (alreadySent) {
  clientText = p.seller_name
    ? 'Seu atendimento já foi encaminhado para ' + p.seller_name + '. Vou manter o acompanhamento por aqui.'
    : 'Seu atendimento já foi encaminhado ao responsável comercial. Vou manter o acompanhamento por aqui.';
} else if (inProgress) {
  clientText = 'Seu atendimento já está em processo de encaminhamento ao responsável comercial.';
} else if (!ready) {
  clientText = p.response_text || 'Seu atendimento está registrado, mas o encaminhamento ainda não foi liberado.';
}

return [{
  json: {
    ...p,
    reservation_ready: ready,
    reservation_already_sent: alreadySent,
    reservation_in_progress: inProgress,
    reservation_reason: r?.motivo || null,
    client_text: clientText
  }
}];
